 (\'Shopify\', \'Marketplace\', \'Offline\') group by 1, 2, 3, 4 ), all_sku_dates as ( select sku_group, date from inventory union select sku_group, date from base_sales ), channels as ( select \'Shopify\' as channel union all select \'Marketplace\' as channel union all select \'Offline\' as channel ), sku_date_channel_base as ( select d.sku_group, d.date, c.channel from all_sku_dates d cross join channels c ) select b.sku_group, b.date, b.channel, coalesce(s.sales_qty, 0) as sales_qty, coalesce(i.total_inv, 0) as total_inv, coalesce(i.online_inv, 0) as online_inv, coalesce(i.offline_inv, 0) as offline_inv from sku_date_channel_base b left join base_sales s on b.sku_group = s.sku_group and b.date = s.date and b.channel = s.channel left join inventory i on b.sku_group = i.sku_group and b.date = i.date ;",
